def clusters(w,tol=1e-6):
    out=[]; 
    order=np.argsort(w); 
    cur=[order[0]]
    for k in order[1:]:
        if abs(w[k]-w[cur[-1]])<tol: cur.append(k)
        else: out.append(cur); cur=[k]
    out.append(cur); return out
